import {fresh,act,restore,validFlavor} from './game.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let s=restore(localStorage.getItem('room-between-save')), lang=localStorage.getItem('room-between-lang')||'zh',ai=null,busy=false;
const t=(zh,en)=>lang==='zh'?zh:en;
const labels=()=>[t('台灯','Lamp'),t('镜子','Mirror'),t('书','Book'),t('抽屉','Drawer'),t('花园门','Garden door')];
const keys=['lamp','mirror','book','chest','door'];
function txt(el,value){$(el).textContent=value}function save(){try{localStorage.setItem('room-between-save',JSON.stringify(s))}catch{txt('#saved',t('存储不可用','Storage unavailable'))}}
function button(text,cb,cls='primary'){const b=document.createElement('button');b.textContent=text;b.className=cls;b.onclick=cb;return b}
function render(){document.documentElement.lang=lang==='zh'?'zh-CN':'en';txt('#lang',t('EN','中文'));txt('#about',t('玩法','How to play'));txt('#headline',s.door?t('夜晚终于继续了。','The night moves on.'):t('夜晚停在了窗外。','The night waits outside.'));$('#subtitle').innerHTML=t('一盏灯，一面镜子，一扇还没打开的门。<br>先找到光要去的地方。','A lamp, a mirror, a door that hasn’t opened yet.<br>Find where the light wants to go.');txt('#chapter',t('第一章 · 借来的月光','Chapter 01 · Borrowed moonlight'));const count=[s.light,s.chest,s.door].filter(Boolean).length;txt('#step',`${count} / 3 ${t('道谜题','puzzles')}`);$('#progress').style.width=`${count/3*100}%`;txt('#saved',t('进度自动保存','Progress saved locally'));txt('#reset',t('重新开始 ↺','Start again ↺'));txt('#scene-note',s.door?t('花园的风，终于进来了','The garden breeze finds its way in'):s.chest?t('叶片记得回家的方向','The leaf remembers the way home'):s.light?t('光落在了书页上','The light has found the page'):t('点亮台灯，开始探索','Light the lamp to begin'));txt('#engine',s.source==='HANDCRAFTED'?t('手工谜题 · 可离线游玩','Handcrafted · works offline'):s.source==='ON_DEVICE'?t('故事来自设备端 AI','Story generated on device'):s.source==='IN_CLOUD'?t('故事来自云端 AI','Story generated in cloud'):t('AI 故事 · 来源未报告','AI story · source unknown'));txt('#panel-eyebrow',t('你的发现','YOUR DISCOVERIES'));txt('#inventory-title',t('口袋里的线索','IN YOUR POCKET'));txt('#hint',t('给我一点提示 ↗','A little hint ↗'));txt('#custom-title',t('让你的房间成为下一章。','Let your room become the next chapter.'));txt('#custom-copy',t('写下三件身边的物品。它们会代替灯、镜子和书，进入这段故事。','Choose three everyday objects to take the place of the lamp, mirror and book.'));txt('#custom',t('放入我的物品 ↗','Use my objects ↗'));txt('#settings',t('AI 设置','AI settings'));txt('#version',ai?t('试玩版 01 · Firebase 已配置，实际推理待生成后验证','Prototype 01 · Firebase configured; generate a story to verify inference'):t('试玩版 01 · 手工谜题已可玩，Firebase AI 尚未连接','Prototype 01 · Handcrafted puzzles playable; Firebase AI not connected'));
$('#lamp-glow').style.opacity=s.lamp?'1':'0';$('#beam').style.opacity=s.lamp&&s.angle===90?'.24':'0';$('#star-code').style.opacity=s.light?'1':'0';$('#mirror-art').style.filter=`brightness(${s.angle===90?1.35:1})`;$('#garden-art').style.display=s.door?'block':'none';$('.scene').classList.toggle('success',s.door);
$$('.hotspot').forEach((b,i)=>{b.classList.toggle('active',s.selected===keys[i]);b.querySelector('b').textContent=labels()[i];});
$('#items').replaceChildren();for(const [flag,text] of [[s.light,'417'],[s.chest,t('◇ 黄铜叶片 · 北 → 东 → 西','◇ Brass leaf · N → E → W')],[s.door,t('✧ 一缕花园的风','✧ A garden breeze')]])if(flag){const p=document.createElement('span');p.className='token';p.textContent=text;$('#items').append(p)}if(!count){const p=document.createElement('span');p.className='empty';p.textContent=t('暂时空着','Nothing here yet');$('#items').append(p)}renderPanel();}
function action(a){const r=act(s,a);s=r.state;save();render();const msgs={needLight:t('密码还藏在光里。先看看灯和镜子。','The code is still hidden in the light. Try the lamp and mirror.'),wrongCode:t('锁没有转动，再看看书页。','The lock stays still. Look at the page again.'),unlocked:t('抽屉打开了，你获得一枚黄铜叶片。','The drawer opens. You found a brass leaf.'),needLeaf:t('门上的凹槽，缺少一枚叶片。','A leaf-shaped piece is missing from the door.'),wrongPath:t('叶片轻轻一颤，方向回到了起点。','The leaf trembles. Start the sequence again.'),step:t('门里传来很轻的风声。','A quiet breeze answers from behind the door.'),opened:t('门开了。这一次，月光落在了你身上。','The door opens. This time, the moonlight falls on you.')};txt('#feedback',msgs[r.result]||'');}
function renderPanel(){const k=s.selected;$('#controls').replaceChildren();txt('#feedback','');txt('#hint-copy','');txt('#item-num',k?`0${keys.indexOf(k)+1}`:'—');if(!k){txt('#object-title',t('房间正在等你。','The room is waiting.'));txt('#object-copy',s.flavor?.intro||t('窗外的月亮停了很久。桌上的纸条写着：「把借来的光还给花园，夜晚就会继续。」','The moon has stayed in the same place for hours. A note on the desk reads: “Return the borrowed light to the garden, and the night will move again.”'));return}
txt('#object-title',labels()[keys.indexOf(k)]);const c=$('#controls');if(k==='lamp'){txt('#object-copy',s.flavor?.lamp||t('灯罩像一封泛黄的信。光的另一头，是桌边那面小镜子。','The lampshade looks like an old letter. At the other end of its light sits a small mirror.'));c.append(button(s.lamp?t('关掉台灯','Turn off lamp'):t('点亮台灯','Turn on lamp'),()=>action({type:'lamp'})));}
if(k==='mirror'){txt('#object-copy',s.flavor?.mirror||t('镜子没有照出你。黄铜边框上刻着：「转过一个直角，光就能记起它的去处。」','The mirror does not show your face. Its brass frame reads: “Turn through a right angle, and the light will remember where to go.”'));const d=document.createElement('div');d.className='dial';const v=document.createElement('span');v.textContent=s.angle+'°';d.append(button('↶',()=>action({type:'rotate',delta:-45})),v,button('↷',()=>action({type:'rotate',delta:45})));c.append(d)}
if(k==='book'){txt('#object-copy',s.light?(s.flavor?.book?s.flavor.book+'\n\n':'')+t('光里出现三个数字：4 · 1 · 7。\n页脚写着：「留给那个锁住秋天的抽屉。」','Three numbers appear in the light: 4 · 1 · 7.\nAt the foot of the page: “For the drawer that keeps autumn.”'):t('这些书页几乎是空白的。纸张里有一些金色的细痕，像在等待某种光。','The pages are almost blank. Fine gold marks in the paper seem to be waiting for a certain kind of light.'));}
if(k==='chest'){txt('#object-copy',s.chest?t('黄铜叶片背面写着：\n「先向北，寻找极星；再向东，借来晨光；最后向西，把夜晚送回花园。」','On the brass leaf:\n“North, to find the pole star. East, to borrow the dawn. West, to return the night to the garden.”'):t('抽屉上有一把三位数的锁。木头有落叶的气味。','A three-digit lock keeps the drawer closed. The wood smells faintly of fallen leaves.'));if(!s.chest){const form=document.createElement('form');const row=document.createElement('div');row.className='code';const input=document.createElement('input');input.inputMode='numeric';input.pattern='[0-9]{3}';input.maxLength=3;input.placeholder='···';input.setAttribute('aria-label',t('三位密码','Three-digit code'));input.autocomplete='off';row.append(input);const b=button(t('打开抽屉','Open drawer'),()=>{});b.type='submit';form.append(row,b);form.onsubmit=e=>{e.preventDefault();action({type:'unlock',code:input.value})};c.append(form)}}
if(k==='door'){txt('#object-copy',s.door?(s.flavor?.ending||t('你走进了一个没有围墙的花园。刚才那间房，还在身后安静地亮着。\n你把借来的月光，留在了这里。','You step into a garden without walls. The little room glows quietly behind you.\nYou leave the borrowed moonlight here.')):s.chest?t('把叶片放入凹槽。它可以指向四个方向。按照叶片背面的顺序，轻轻转动它。','Place the leaf in the recess. Turn it in the order written on its back.'):t('门上有一枚叶片形状的凹槽。门外有风，但还听不清。','A leaf-shaped recess marks the door. There is wind on the other side, too quiet to hear.'));if(s.chest&&!s.door){const d=document.createElement('div');d.className='directions';['N','E','S','W'].forEach((v,i)=>d.append(button(t(['北','东','南','西'][i],v),()=>action({type:'direction',value:v}))));c.append(d);const p=document.createElement('p');p.textContent=s.path.join(' → ')||'○ → ○ → ○';c.append(p)}if(s.door)c.append(button(t('把下一章带到我的房间','Bring the next chapter into my room'),custom));}}
$$('.hotspot').forEach(b=>b.onclick=()=>{s.selected=b.dataset.object;render();});$('#hint').onclick=()=>{const msg=!s.lamp?t('先点一下台灯，再按「点亮台灯」。','Click the lamp, then turn it on.'):!s.light?t('转动镜子到 90°。让台灯的光落到书页上。','Rotate the mirror to 90° to send the light to the book.'):!s.chest?t('书页里的 417，就是抽屉的密码。','The 417 on the page opens the drawer.'):!s.door?t('叶片的三个方向是：北、东、西。错了可以重来。','The leaf points North, East, then West. A wrong turn restarts the sequence.'):t('你已经把月光还给花园了。可以试试加入自己的物品。','The moonlight is home. Try adding your own objects.');s.hints++;save();txt('#hint-copy',msg)};
function modal(html){$('#modal-body').innerHTML=html;$('#modal').showModal()}$('.close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});$('#lang').onclick=()=>{lang=lang==='zh'?'en':'zh';localStorage.setItem('room-between-lang',lang);render()};$('#about').onclick=()=>modal(t('<p class="eyebrow">HOW TO PLAY</p><h2>把光还给花园。</h2><p>点击房间里的编号，检查物品并操作。先解开光的谜题，再打开抽屉，最后打开花园门。</p><p>不需要在现实中移动物品，所有操作都在屏幕里完成。卡住时可以点击提示。进度只存在当前浏览器。</p><p>当前默认故事和谜题为手工设计。AI 功能需要连接 Firebase 后才能生成新故事。</p>','<p class="eyebrow">HOW TO PLAY</p><h2>Return the light.</h2><p>Explore numbered objects. Solve the light puzzle, open the drawer, then find the garden.</p><p>Everything happens on screen. No real objects need to be moved. Ask for a hint any time. Progress stays in this browser.</p><p>The default story and puzzles are handcrafted. New AI stories require a connected Firebase project.</p>'));
$('#reset').onclick=()=>{modal(`<h2>${t('重新开始这一夜？','Start this night again?')}</h2><p>${t('当前线索和谜题进度会被清空。','This clears the current clues and puzzle progress.')}</p><button class="primary" id="confirm-reset">${t('重新开始','Start again')}</button>`);$('#confirm-reset').onclick=()=>{s=fresh();save();render();$('#modal').close()}};
function custom(){modal(`<p class="eyebrow">YOUR ORDINARY OBJECTS</p><h2>${t('三件物品，一个入口。','Three objects. One entrance.')}</h2><p>${t('写物品名称就好，不需要照片或私人信息。尚未连接 AI 时，会使用手写的故事模板。','Object names are enough. No photos or personal information. Without AI, a handwritten story template is used.')}</p><label>${t('一件代表光的物品','Something that means light')}<input id="obj1" maxlength="24" placeholder="${t('例如：玻璃杯','e.g. a glass')}" required></label><label>${t('一件代表倒影的物品','Something that means reflection')}<input id="obj2" maxlength="24" placeholder="${t('例如：银色纽扣','e.g. a silver button')}" required></label><label>${t('一件代表记忆的物品','Something that means memory')}<input id="obj3" maxlength="24" placeholder="${t('例如：旧车票','e.g. an old train ticket')}" required></label><p class="small">${t('创建新故事会重置这一章的谜题进度。','Creating a story resets this chapter’s puzzle progress.')}</p><button id="make-room" class="primary">${ai?t('用 Firebase 生成故事','Generate with Firebase'):t('放入手工故事','Use handwritten story')}</button><p id="generation-status" role="status"></p>`);$('#make-room').onclick=async()=>{if(busy)return;const names=['#obj1','#obj2','#obj3'].map(x=>$(x).value.trim());if(names.some(x=>!x)){txt('#generation-status',t('请填好三个物品名称。','Please enter all three object names.'));return}if(!ai){s=fresh();s.names=names;s.flavor={intro:t(`你把${names.join('、')}放进了故事。房间保留着它们的影子，像保留三封还没寄出的信。`,`You bring ${names.join(', ')} into the story. The room keeps their shadows like three letters not yet sent.`),lamp:t(`${names[0]}成了光的名字。屏幕里的台灯仍在等你点亮。`,`${names[0]} gives the light its name. The lamp on screen waits to be lit.`),mirror:t(`${names[1]}把倒影借给了这面镜子。边框刻着：「转过一个直角。」`,`${names[1]} lends its reflection to the mirror. Its frame reads: “Turn through a right angle.”`),book:t(`${names[2]}被夹在记忆的这一页。`,`${names[2]} rests between these pages of memory.`),ending:t(`花园记住了${names.join('、')}。你离开时，风替你合上了那三封信。`,`The garden remembers ${names.join(', ')}. As you leave, the wind folds the three letters closed.`)};save();render();$('#modal').close();return}busy=true;$('#make-room').disabled=true;txt('#generation-status',t('正在准备模型并生成故事；首次下载可能需要几分钟…','Preparing the model and story; first download may take several minutes…'));try{const r=await ai.generateStory(names,lang,p=>{if($('#generation-status'))txt('#generation-status',t('设备模型下载进度：','Device model download: ')+Math.round(p*100)+'%')});if(!validFlavor(r.story))throw Error('Invalid story schema');s=fresh();s.names=names;s.flavor=r.story;s.source=r.source;save();render();$('#modal').close();}catch{txt('#generation-status',t('AI 未能生成故事。原进度已保留。请检查 Firebase、App Check 和设备支持；可关闭设置后改用手工故事。','AI could not generate a story. Your previous progress is preserved. Check Firebase, App Check and device support, or disconnect AI to use the handwritten story.'));}finally{busy=false;if($('#make-room'))$('#make-room').disabled=false}}}
$('#custom').onclick=custom;
$('#settings').onclick=()=>{modal(`<p class="eyebrow">FIREBASE AI LOGIC</p><h2>${t('连接你的 AI 项目','Connect your AI project')}</h2><p>${t('当前没有预置账号或付费服务。这里只填写 Firebase 网页配置及 App Check 公开站点密钥；不要填写服务账号密钥。配置只保留到刷新页面。','No account or paid service is preconfigured. Use Firebase public web config and the public App Check site key, never service-account secrets. Configuration lasts until page refresh.')}</p><label>Firebase web config (JSON)<textarea id="firebase-config" spellcheck="false" placeholder='{"apiKey":"…","projectId":"…","appId":"…"}'></textarea></label><label>App Check reCAPTCHA v3 site key<input id="appcheck-key" autocomplete="off"></label><label>${t('推理方式','Inference mode')}<select id="mode"><option value="local">${t('仅设备端 · 物品名称不上传云端','Device only · object names stay local')}</option><option value="hybrid">${t('优先设备端 · 允许物品名称发送云端','Prefer device · allow object names in cloud')}</option></select></label><p class="small">${t('请使用已启用 AI Logic 和 App Check 的免费项目。云端使用量受你的项目配额限制；此页面不会开通计费。设备端 AI 需要支持的桌面 Chrome。','Use an AI Logic + App Check enabled free-tier project. Cloud requests use your project quota; this page never enables billing. Local AI requires supported desktop Chrome.')}</p><button class="primary" id="connect-ai">${t('连接项目','Connect project')}</button><button class="quiet" id="disconnect-ai">${t('断开 AI，使用手工故事','Disconnect AI; use handwritten stories')}</button><p id="ai-status" role="status"></p>`);$('#connect-ai').onclick=async()=>{try{const config=JSON.parse($('#firebase-config').value),key=$('#appcheck-key').value.trim(),cloud=$('#mode').value==='hybrid';const m=await import('./firebase.js');m.configure(config,key,cloud);ai=m;render();txt('#ai-status',t('配置已加载。创建物品故事时将发起真实请求；目前尚未验证推理。','Configuration loaded. Creating an object story will make a real request; inference is not yet verified.'));}catch{txt('#ai-status',t('无法加载配置。请检查 JSON 和必填项；若更换项目，请刷新页面。','Could not load configuration. Check JSON and required fields; reload to change projects.'));}};$('#disconnect-ai').onclick=()=>{ai=null;render();$('#modal').close()}};
render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
